<template><section><article v-for="c in threaded" :key="c.id" class="card comment-row" :class="{reply:c.parent_id}"><router-link v-if="authorCharacter(c)" :to="'/characters/'+authorCharacter(c).id" class="comment-author character-themed character-name" :style="characterTheme(authorCharacter(c))" :aria-label="authorCharacter(c).name + ' 캐릭터 소개 보기'"><Portrait :character="authorCharacter(c)"/>{{c.character_id ? authorCharacter(c).name : owner(c.owner_id)}}</router-link><span v-else class="muted">{{c.character_id?'삭제된 캐릭터 · ':''}}{{owner(c.owner_id)}}</span><p><MentionText :text="c.body" :characters="characters"/></p><div class="toolbar"><button v-if="!c.parent_id" class="outline-button" @click="reply=c;draft.id=null">답글</button><template v-if="c.owner_id===me.id || ['admin','superadmin'].includes(me.role)"><button class="outline-button" @click="edit(c)">수정</button><button class="secondary-button" @click="$emit('remove',c.id)">삭제</button></template></div></article><p v-if="!comments.length" class="muted">아직 남겨진 교류 기록이 없습니다.</p><form class="card comment-form" @submit.prevent="submit"><p v-if="reply">답글: {{reply.body.slice(0,60)}} <button type="button" @click="reply=null">취소</button></p><h4>{{draft.id?'댓글 수정':'교류 기록 남기기'}}</h4><select v-model="draft.character_id" class="form-input" aria-label="댓글 작성 캐릭터"><option :value="null">오너 이름으로 작성</option><option v-for="c in mine" :key="c.id" :value="c.id">{{c.name}}</option></select><textarea v-model="draft.body" class="form-textarea" required maxlength="20000" rows="4" aria-label="댓글 내용"></textarea><div class="toolbar"><select class="form-input" aria-label="멘션할 캐릭터" @change="mention($event)"><option value="">캐릭터 멘션 추가</option><option v-for="c in characters" :key="c.id" :value="c.id">{{c.name}}</option></select><button class="primary-button" :disabled="pending">{{draft.id?'수정 저장':'댓글 남기기'}}</button><button v-if="draft.id" class="secondary-button" type="button" @click="reset">취소</button></div><p class="muted">같은 이름의 캐릭터도 고유 ID로 구분됩니다.</p></form></section></template>
<script setup>
import {ref,computed} from 'vue';import {characterTheme} from './character-theme.mjs';import {commentCharacter} from './domain.mjs';import Portrait from './Portrait.vue';import MentionText from './MentionText.vue';const props=defineProps({comments:Array,characters:Array,members:Array,mine:Array,me:Object});const emit=defineEmits(['submit','remove']);const draft=ref({character_id:null,body:''}),reply=ref(null),pending=ref(false);
const threaded=computed(()=>props.comments.filter(c=>!c.parent_id||!props.comments.some(p=>p.id===c.parent_id)).flatMap(c=>[c,...props.comments.filter(r=>r.parent_id===c.id)]));function authorCharacter(comment){return commentCharacter(comment,props.characters,props.members);}function byId(id){return props.characters.find(c=>c.id===id);}function owner(id){return props.members.find(m=>m.id===id)?.nickname||'오너';}function edit(c){draft.value={...c};reply.value=null;}function reset(){draft.value={character_id:null,body:''};reply.value=null;pending.value=false;}function mention(e){const c=byId(e.target.value);if(c)draft.value.body+=' @['+c.name.replace(/\]/g,'')+']('+c.id+')';e.target.value='';}function submit(){pending.value=true;emit('submit',{...draft.value,parent_id:draft.value.id?draft.value.parent_id:reply.value?.id||null},ok=>{if(ok)reset();else pending.value=false;});}
</script>
